import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@/lib/supabase-server';
import OpenAI from 'openai';

const SYSTEM_PROMPT = `You are an expert quoting assistant for service businesses (construction, painting, cleaning, plumbing, electrical work, landscaping, renovation, etc.).

YOUR ROLE:
- Help users build professional quotes by discussing their job requirements
- Ask smart clarifying questions (area sizes, materials, location, complexity)
- Reason about realistic pricing for the user's region and currency
- Choose the right pricing mode for each service: "sqm" (per square meter), "hour" (per hour), or "fixed" (fixed price)
- Be conversational and natural, like a knowledgeable colleague

PRICING GUIDELINES:
- Always consider the user's country/region when suggesting prices
- Use your knowledge of typical market rates for common services
- When unsure, give a reasonable range and explain your reasoning
- Factor in complexity, materials, labor, and regional cost of living
- If the user mentions a specific city or country, adjust pricing accordingly

WHEN YOU HAVE ENOUGH INFORMATION to build a quote, call the fill_quote function with structured data. You can do this at any point when you feel you have sufficient detail. Always tell the user what you're suggesting and why.

IMPORTANT:
- Always respond in the same language the user writes in
- Be concise but helpful — this is a mobile app
- If the user gives vague info, ask ONE focused follow-up question at a time
- When suggesting prices, briefly explain your reasoning`;

const FILL_QUOTE_TOOL: OpenAI.Chat.Completions.ChatCompletionTool = {
    type: 'function',
    function: {
        name: 'fill_quote',
        description: 'Fill the quote form with services, pricing, and details based on the conversation. Call this when you have enough information to build a quote.',
        parameters: {
            type: 'object',
            properties: {
                services: {
                    type: 'array',
                    description: 'List of services to include in the quote',
                    items: {
                        type: 'object',
                        properties: {
                            title: {
                                type: 'string',
                                description: 'Service name (e.g. "Wall Painting", "Floor Tiling")',
                            },
                            description: {
                                type: 'string',
                                description: 'Brief description of the service scope',
                            },
                            pricingMode: {
                                type: 'string',
                                enum: ['sqm', 'hour', 'fixed'],
                                description: 'Pricing model: sqm (per m²), hour (per hour), or fixed (lump sum)',
                            },
                            quantity: {
                                type: 'string',
                                description: 'Number of units (m² or hours). Leave empty for fixed pricing.',
                            },
                            unitPrice: {
                                type: 'string',
                                description: 'Price per unit (per m² or per hour). Leave empty for fixed pricing.',
                            },
                            fixedPrice: {
                                type: 'string',
                                description: 'Fixed total price for this service. Only used when pricingMode is "fixed".',
                            },
                        },
                        required: ['title', 'pricingMode'],
                    },
                },
                baseValue: {
                    type: 'string',
                    description: 'Total base value before tax (sum of all services)',
                },
                estimatedTime: {
                    type: 'string',
                    description: 'Estimated time to complete the work (e.g. "5-7 working days")',
                },
                expirationDate: {
                    type: 'string',
                    description: 'Quote validity period (e.g. "Valid for 30 days")',
                },
                paymentConditions: {
                    type: 'string',
                    description: 'Payment terms (e.g. "50% upfront, 50% on completion")',
                },
            },
            required: ['services', 'baseValue'],
        },
    },
};

export async function POST(request: NextRequest) {
    try {
        // Auth check
        const supabase = await createClient();
        const { data: { user }, error: authError } = await supabase.auth.getUser();
        if (authError || !user) {
            return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
        }

        const apiKey = process.env.OPENAI_API_KEY;
        if (!apiKey) {
            return NextResponse.json({
                error: 'AI not configured',
                message: 'The AI assistant is not yet configured. Please add your OpenAI API key to get started.',
            }, { status: 503 });
        }

        const { messages, settings } = await request.json() as {
            messages: { role: 'user' | 'assistant'; content: string }[];
            settings?: { currency?: string; taxCountry?: string };
        };

        if (!messages || messages.length === 0) {
            return NextResponse.json({ error: 'No messages provided' }, { status: 400 });
        }

        // Build context-aware system prompt
        const contextInfo = settings
            ? `\n\nUSER CONTEXT:\n- Currency: ${settings.currency || '€'}\n- Tax country: ${settings.taxCountry || 'uk'}\nUse this context to give location-appropriate pricing suggestions.`
            : '';

        const openai = new OpenAI({ apiKey });

        const completion = await openai.chat.completions.create({
            model: 'gpt-4o-mini',
            messages: [
                { role: 'system', content: SYSTEM_PROMPT + contextInfo },
                ...messages,
            ],
            tools: [FILL_QUOTE_TOOL],
            tool_choice: 'auto',
            max_tokens: 1024,
            temperature: 0.7,
        });

        const choice = completion.choices[0];
        const assistantMessage = choice.message;

        // Check if the AI called the fill_quote function
        let quoteData = null;
        if (assistantMessage.tool_calls && assistantMessage.tool_calls.length > 0) {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const fillCall = assistantMessage.tool_calls.find(
                (tc: any) => tc.function?.name === 'fill_quote'
            );
            if (fillCall) {
                try {
                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                    quoteData = JSON.parse((fillCall as any).function.arguments);
                } catch {
                    console.error('Failed to parse fill_quote arguments');
                }
            }
        }

        return NextResponse.json({
            message: assistantMessage.content || '',
            quoteData,
        });
    } catch (err) {
        console.error('Chat API error:', err);
        const message = err instanceof Error ? err.message : 'Unknown error';
        return NextResponse.json({ error: 'Chat failed', message }, { status: 500 });
    }
}

'use client';

import { useState, useEffect } from 'react';
import { useSettings } from '../context/SettingsContext';
import { usePDF } from '../context/PDFContext';
import { downloadPDF } from '../utils/pdfGenerator';
import styles from './ActionButtons.module.css';

export default function ActionButtons() {
    const { settings } = useSettings();
    const { capturePDF } = usePDF();

    // Local editable message — initialized from Settings default
    const [message, setMessage] = useState(settings.message);

    // Sync with settings when the default changes (e.g. user updates Settings drawer)
    useEffect(() => { setMessage(settings.message); }, [settings.message]);

    /* ── Share helper — tries Web Share API with file, otherwise falls back ── */
    async function shareOrFallback(
        blob: Blob,
        fallbackAction: () => void,
    ) {
        try {
            const file = new File([blob], 'quote.pdf', { type: 'application/pdf' });

            // Check if Web Share with files is supported
            if (navigator.share && navigator.canShare && navigator.canShare({ files: [file] })) {
                await navigator.share({
                    title: 'Quote',
                    text: settings.message || 'Please find the quote attached',
                    files: [file],
                });
                return; // shared successfully
            }
        } catch (err: unknown) {
            // User cancelled the share sheet — do nothing
            if (err instanceof Error && err.name === 'AbortError') return;
            console.warn('Web Share failed, using fallback:', err);
        }

        // Fallback: download PDF + open the appropriate link
        downloadPDF(blob, 'quote.pdf');
        fallbackAction();
    }

    /* ── Email handler ── */
    const handleEmail = async () => {
        const blob = await capturePDF();
        if (!blob) return;

        const subject = `Quote from ${settings.companyName || 'Quote Flow'}`;
        const body = message || 'Hello! Please find attached the quote for your review.';
        const mailtoUrl = `mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;

        await shareOrFallback(blob, () => {
            window.location.href = mailtoUrl;
        });
    };

    /* ── Share handler ── */
    const handleShare = async () => {
        const blob = await capturePDF();
        if (!blob) return;

        await shareOrFallback(blob, () => {
            // Fallback: just download, no specific link
        });
    };

    /* ── WhatsApp handler ── */
    const handleWhatsapp = async () => {
        const blob = await capturePDF();
        if (!blob) return;

        const msg = message || 'Hello! Please find attached the quote for your review.';
        const whatsappUrl = `https://wa.me/?text=${encodeURIComponent(msg)}`;

        await shareOrFallback(blob, () => {
            window.open(whatsappUrl, '_blank');
        });
    };

    return (
        <>
            {/* Action Buttons UI */}
            <div className={styles.actionSection}>
                <h2 className="shared-section-title">Pre-defined message</h2>

                <div className={styles.messageGroup}>
                    <textarea
                        id="quote-message"
                        className="shared-textarea"
                        placeholder="Message sent with the quote..."
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                    />
                    <p style={{ fontSize: '0.75rem', color: '#666', marginTop: '0.35rem' }}>
                        Default set in Settings
                    </p>
                </div>

                <h3 className="shared-subsection-title">Send by:</h3>

                <div className={styles.buttonsGrid}>
                    <button
                        className={`${styles.actionBtn} ${styles.emailBtn}`}
                        onClick={handleEmail}
                        aria-label="Send via Email"
                    >
                        Email
                    </button>
                    <button
                        className={`${styles.actionBtn} ${styles.shareBtn}`}
                        onClick={handleShare}
                        aria-label="Share quote"
                    >
                        Share
                    </button>
                    <button
                        className={`${styles.actionBtn} ${styles.whatsappBtn}`}
                        onClick={handleWhatsapp}
                        aria-label="Send via Whatsapp"
                    >
                        Whatsapp
                    </button>
                </div>
            </div>
        </>
    );
}

'use client';

import { useClient } from '../context/ClientContext';
import styles from './ClientInfo.module.css';

export default function ClientInfo() {
    const { client, updateClient } = useClient();

    return (
        <div className={styles.section}>
            <h2 className="shared-section-title">Client Information</h2>
            <div className={styles.fieldsContainer}>
                <div className={styles.fieldGroup}>
                    <label htmlFor="client-name" className="sr-only">
                        Client's Name
                    </label>
                    <input
                        id="client-name"
                        type="text"
                        placeholder="Client's Name"
                        className={styles.inputField}
                        value={client.clientName}
                        onChange={(e) => updateClient({ clientName: e.target.value })}
                    />
                </div>

                <div className={styles.fieldGroup}>
                    <label htmlFor="client-email" className="sr-only">
                        Email
                    </label>
                    <input
                        id="client-email"
                        type="email"
                        placeholder="Email"
                        className={styles.inputField}
                        value={client.email}
                        onChange={(e) => updateClient({ email: e.target.value })}
                    />
                </div>

                <div className={styles.fieldGroup}>
                    <label htmlFor="client-whatsapp" className="sr-only">
                        Whatsapp
                    </label>
                    <input
                        id="client-whatsapp"
                        type="tel"
                        placeholder="Whatsapp"
                        className={styles.inputField}
                        value={client.whatsapp}
                        onChange={(e) => updateClient({ whatsapp: e.target.value })}
                    />
                </div>

                <div className={styles.fieldGroup}>
                    <label htmlFor="service-title" className="sr-only">
                        Service Title
                    </label>
                    <input
                        id="service-title"
                        type="text"
                        placeholder="Service Title"
                        className={styles.inputField}
                        value={client.serviceTitle}
                        onChange={(e) => updateClient({ serviceTitle: e.target.value })}
                    />
                </div>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useRef, useState, useCallback } from 'react';
import { useQuote } from '../context/QuoteContext';
import { useSettings } from '../context/SettingsContext';
import { usePDF } from '../context/PDFContext';
import { downloadPDF } from '../utils/pdfGenerator';
import { getTaxLabels } from '../utils/taxLabels';
import styles from './PDFPreview.module.css';

const PAGE_WIDTH = 595; // A4 width at 72dpi

export default function PDFPreview() {
    const { quote } = useQuote();
    const { settings } = useSettings();
    const { previewRef, capturePDF } = usePDF();
    const scalerRef = useRef<HTMLDivElement>(null);
    const localPageRef = useRef<HTMLDivElement>(null);
    const [scale, setScale] = useState(1);
    const [scaledH, setScaledH] = useState<number | undefined>(undefined);

    // Register the local page ref into the shared PDF context
    useEffect(() => {
        previewRef.current = localPageRef.current;
    });

    const recalc = useCallback(() => {
        if (!scalerRef.current || !localPageRef.current) return;
        const containerW = scalerRef.current.offsetWidth;
        const s = containerW / PAGE_WIDTH;
        setScale(s);
        const pageH = localPageRef.current.offsetHeight;
        setScaledH(pageH * s);
    }, []);

    useEffect(() => {
        recalc();
        const ro = new ResizeObserver(recalc);
        if (scalerRef.current) ro.observe(scalerRef.current);
        if (localPageRef.current) ro.observe(localPageRef.current);
        return () => ro.disconnect();
    }, [recalc]);

    const settingsVat = settings.vatEnabled ? settings.vatPercentage : 0;
    const vatPercent = quote.vatOverride !== '' ? (parseFloat(quote.vatOverride) || 0) : settingsVat;
    const baseVal = parseFloat(quote.baseValue) || 0;
    const totalValue = baseVal + (baseVal * vatPercent) / 100;

    const taxLabels = getTaxLabels(settings.taxCountry);

    const handleDownload = async () => {
        const blob = await capturePDF();
        if (blob) downloadPDF(blob, 'quote.pdf');
    };

    // Only show services that have some content filled in
    const filledServices = quote.services.filter(
        (s) => s.title || s.description || s.fixedPrice || (s.quantity && s.unitPrice)
    );

    const getUnitLabel = (mode: string) => {
        if (mode === 'sqm') return 'm²';
        if (mode === 'hour') return 'hr';
        return '';
    };

    return (
        <div className={styles.previewContainer}>
            <h2 className={styles.sectionTitle}>PDF Preview</h2>

            <div ref={scalerRef} className={styles.previewScaler} style={{ height: scaledH }}>
                <div
                    ref={localPageRef}
                    className={styles.previewFrame}
                    style={{
                        transform: `scale(${scale})`,
                        transformOrigin: 'top left',
                    }}
                >
                    {/* PDF Header */}
                    <div className={styles.pdfHeader}>
                        <div className={styles.companyInfo}>
                            {settings.companyName && (
                                <h3 className={styles.companyName}>
                                    {settings.companyName}
                                </h3>
                            )}
                            {settings.phone && (
                                <p className={styles.companyDetail}>
                                    {settings.phone}
                                </p>
                            )}
                            {settings.email && (
                                <p className={styles.companyDetail}>
                                    {settings.email}
                                </p>
                            )}
                            {settings.website && (
                                <p className={styles.companyDetail}>
                                    {settings.website}
                                </p>
                            )}
                        </div>
                        {settings.logoUrl && (
                            <div className={styles.logoArea}>
                                <img
                                    src={settings.logoUrl}
                                    alt="Company logo"
                                    className={styles.logoImage}
                                />
                            </div>
                        )}
                    </div>

                    {/* Quote Description Bar */}
                    <div
                        className={styles.descriptionBar}
                        style={{ backgroundColor: settings.brandColor }}
                    >
                        {settings.quoteDescription}
                    </div>

                    {/* Services — only show filled ones */}
                    <div className={styles.servicesArea}>
                        {filledServices.map((service) => {
                            let priceDisplay = '';

                            if (service.pricingMode === 'fixed') {
                                if (service.fixedPrice) {
                                    priceDisplay = `${parseFloat(service.fixedPrice).toFixed(2)} ${settings.currency}`;
                                }
                            } else if (service.quantity && service.unitPrice) {
                                const unit = getUnitLabel(service.pricingMode);
                                const total = (
                                    parseFloat(service.quantity) *
                                    parseFloat(service.unitPrice)
                                ).toFixed(2);
                                priceDisplay = `${total} ${settings.currency} (${service.quantity} ${unit})`;
                            }

                            return (
                                <div key={service.id} className={styles.serviceItem}>
                                    <div className={styles.serviceRow}>
                                        {service.title && (
                                            <span className={styles.serviceTitle}>
                                                {service.title}
                                            </span>
                                        )}
                                        {priceDisplay && (
                                            <span className={styles.servicePrice}>
                                                {priceDisplay}
                                            </span>
                                        )}
                                    </div>
                                    {service.description && (
                                        <p className={styles.serviceDescription}>
                                            {service.description}
                                        </p>
                                    )}
                                </div>
                            );
                        })}
                    </div>

                    {/* Totals Divider Bar */}
                    <div
                        className={styles.totalsBar}
                        style={{ backgroundColor: settings.brandColor }}
                    ></div>

                    {/* Bottom Section: Values on top, Footer below */}
                    <div className={styles.bottomSection}>
                        <div className={styles.valuesRight}>
                            <p className={styles.baseValueLine}>
                                {taxLabels.priceExcl}: {settings.currency}{' '}
                                {baseVal > 0 ? baseVal.toFixed(2) : '0.00'}
                            </p>
                            <p className={styles.baseValueLine}>
                                {taxLabels.taxName} {vatPercent}%: {settings.currency}{' '}
                                {baseVal > 0 ? (totalValue - baseVal).toFixed(2) : '0.00'}
                            </p>
                            <p className={styles.totalValueLine}>
                                {taxLabels.totalIncl}: {settings.currency}{' '}
                                {totalValue > 0 ? totalValue.toFixed(2) : '0.00'}
                            </p>
                        </div>
                        <div className={styles.footerLeft}>
                            {quote.estimatedTime && (
                                <p className={styles.footerLine}>
                                    {quote.estimatedTime}
                                </p>
                            )}
                            {quote.expirationDate && (
                                <p className={styles.footerLine}>
                                    {quote.expirationDate}
                                </p>
                            )}
                            {quote.paymentConditions && (
                                <p className={styles.footerLine}>
                                    {quote.paymentConditions}
                                </p>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            <button className={styles.downloadBtn} onClick={handleDownload}>Download PDF</button>
        </div>
    );
}

'use client';

import { useState, useRef, useCallback } from 'react';
import Cropper, { Area } from 'react-easy-crop';
import { useSettings } from '../context/SettingsContext';
import { TAX_LABELS } from '../utils/taxLabels';
import styles from './SettingsDrawer.module.css';
import ClientInfoStyles from './ClientInfo.module.css';

// Utility: apply crop to a canvas and return a data URL (PNG to keep transparency)
function getCroppedImg(imageSrc: string, crop: Area): Promise<string> {
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = crop.width;
            canvas.height = crop.height;
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            ctx.drawImage(
                img,
                crop.x, crop.y, crop.width, crop.height,
                0, 0, crop.width, crop.height
            );

            resolve(canvas.toDataURL('image/png'));
        };
        img.src = imageSrc;
    });
}

export default function SettingsDrawer() {
    const { settings, updateSettings, saveSettings } = useSettings();
    const [isOpen, setIsOpen] = useState(false);
    const [localLogoUrl, setLocalLogoUrl] = useState<string | null>(settings.logoUrl);
    const fileInputRef = useRef<HTMLInputElement>(null);

    // Crop modal state
    const [cropSrc, setCropSrc] = useState<string | null>(null);   // raw image for cropping
    const [crop, setCrop] = useState({ x: 0, y: 0 });
    const [zoom, setZoom] = useState(1);
    const [croppedArea, setCroppedArea] = useState<Area | null>(null);
    const [cropAspect, setCropAspect] = useState<number | undefined>(undefined); // undefined = free

    const onCropComplete = useCallback((_: Area, croppedAreaPixels: Area) => {
        setCroppedArea(croppedAreaPixels);
    }, []);

    const handleCropConfirm = async () => {
        if (!cropSrc || !croppedArea) return;
        const cropped = await getCroppedImg(cropSrc, croppedArea);
        setLocalLogoUrl(cropped);
        setCropSrc(null);
        setCrop({ x: 0, y: 0 });
        setZoom(1);
        setCropAspect(undefined);
    };

    const handleCropCancel = () => {
        setCropSrc(null);
        setCrop({ x: 0, y: 0 });
        setZoom(1);
        setCropAspect(undefined);
    };

    const handleLogoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validate type
        const validTypes = ['image/png', 'image/jpeg', 'image/svg+xml', 'image/webp'];
        if (!validTypes.includes(file.type)) {
            alert('Please upload a PNG, JPG, SVG, or WebP image.');
            return;
        }

        // For SVGs, read directly (they scale perfectly, no crop needed)
        if (file.type === 'image/svg+xml') {
            const reader = new FileReader();
            reader.onload = () => setLocalLogoUrl(reader.result as string);
            reader.readAsDataURL(file);
            e.target.value = '';
            return;
        }

        // For raster images: open the crop modal
        const reader = new FileReader();
        reader.onload = () => {
            setCropSrc(reader.result as string);
        };
        reader.readAsDataURL(file);

        // Reset input so the same file can be re-selected
        e.target.value = '';
    };

    // Local state mirrors context so user can cancel without saving
    const [localCompanyName, setLocalCompanyName] = useState(settings.companyName);
    const [localEmail, setLocalEmail] = useState(settings.email);
    const [localPhone, setLocalPhone] = useState(settings.phone);
    const [localWebsite, setLocalWebsite] = useState(settings.website);
    const [localBrandColor, setLocalBrandColor] = useState(settings.brandColor);
    const [localCurrency, setLocalCurrency] = useState(settings.currency);
    const [localVatEnabled, setLocalVatEnabled] = useState(settings.vatEnabled);
    const [localVatPercentage, setLocalVatPercentage] = useState(settings.vatPercentage);
    const [localMessage, setLocalMessage] = useState(settings.message);
    const [localQuoteDescription, setLocalQuoteDescription] = useState(settings.quoteDescription);
    const [localTaxCountry, setLocalTaxCountry] = useState(settings.taxCountry);

    const handleOpen = () => {
        // Sync local state from context when opening
        setLocalCompanyName(settings.companyName);
        setLocalEmail(settings.email);
        setLocalPhone(settings.phone);
        setLocalWebsite(settings.website);
        setLocalLogoUrl(settings.logoUrl);
        setLocalBrandColor(settings.brandColor);
        setLocalCurrency(settings.currency);
        setLocalVatEnabled(settings.vatEnabled);
        setLocalVatPercentage(settings.vatPercentage);
        setLocalMessage(settings.message);
        setLocalQuoteDescription(settings.quoteDescription);
        setLocalTaxCountry(settings.taxCountry);
        setIsOpen(true);
    };

    const handleSave = async () => {
        const newSettings = {
            companyName: localCompanyName,
            email: localEmail,
            phone: localPhone,
            website: localWebsite,
            logoUrl: localLogoUrl,
            brandColor: localBrandColor,
            currency: localCurrency,
            vatEnabled: localVatEnabled,
            vatPercentage: localVatPercentage,
            message: localMessage,
            quoteDescription: localQuoteDescription,
            taxCountry: localTaxCountry,
        };

        // Update context state for immediate UI reflection
        updateSettings(newSettings);

        // Persist to Supabase — pass data directly to avoid stale closure
        try {
            await saveSettings(newSettings);
        } catch (err) {
            console.error('Failed to save settings:', err);
        }

        setIsOpen(false);
    };

    const handleToggle = () => {
        if (isOpen) {
            setIsOpen(false);
        } else {
            handleOpen();
        }
    };

    return (
        <>
            {/* Crop Modal Overlay */}
            {cropSrc && (
                <div className={styles.cropOverlay}>
                    <div className={styles.cropContainer}>
                        <Cropper
                            image={cropSrc}
                            crop={crop}
                            zoom={zoom}
                            aspect={cropAspect}
                            onCropChange={setCrop}
                            onZoomChange={setZoom}
                            onCropComplete={onCropComplete}
                        />
                    </div>
                    <div className={styles.cropControls}>
                        <div className={styles.aspectRow}>
                            <span className={styles.aspectLabel}>Shape:</span>
                            <button
                                type="button"
                                className={`${styles.aspectBtn} ${cropAspect === undefined ? styles.aspectBtnActive : ''}`}
                                onClick={() => setCropAspect(undefined)}
                            >
                                Free
                            </button>
                            <button
                                type="button"
                                className={`${styles.aspectBtn} ${cropAspect === 1 ? styles.aspectBtnActive : ''}`}
                                onClick={() => setCropAspect(1)}
                            >
                                Square
                            </button>
                            <button
                                type="button"
                                className={`${styles.aspectBtn} ${cropAspect === 16 / 9 ? styles.aspectBtnActive : ''}`}
                                onClick={() => setCropAspect(16 / 9)}
                            >
                                Wide
                            </button>
                        </div>
                        <label className={styles.zoomLabel}>
                            Zoom
                            <input
