'use client';

import { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { useQuote } from './QuoteContext';

interface ClientData {
    clientName: string;
    email: string;
    whatsapp: string;
    serviceTitle: string;
}

interface ClientContextType {
    client: ClientData;
    updateClient: (updates: Partial<ClientData>) => void;
    clearClient: () => void;
}

const defaultClient: ClientData = {
    clientName: '',
    email: '',
    whatsapp: '',
    serviceTitle: '',
};

const ClientContext = createContext<ClientContextType | undefined>(undefined);

export function ClientProvider({ children }: { children: ReactNode }) {
    const [client, setClient] = useState<ClientData>(defaultClient);
    const { currentQuoteId } = useQuote();

    // Clear client data when starting a new quote
    useEffect(() => {
        if (!currentQuoteId) {
            setClient(defaultClient);
        }
    }, [currentQuoteId]);

    const updateClient = (updates: Partial<ClientData>) => {
        setClient((prev) => ({ ...prev, ...updates }));
    };

    const clearClient = () => {
        setClient(defaultClient);
    };

    return (
        <ClientContext.Provider value={{ client, updateClient, clearClient }}>
            {children}
        </ClientContext.Provider>
    );
}

export function useClient() {
    const context = useContext(ClientContext);
    if (!context) {
        throw new Error('useClient must be used within a ClientProvider');
    }
    return context;
}

'use client';

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { createClient } from '@/lib/supabase-browser';
import { useAuth } from './AuthContext';

export type PricingMode = 'sqm' | 'hour' | 'fixed';

export interface ServiceBlock {
    id: string;
    title: string;
    description: string;
    pricingMode: PricingMode;
    quantity: string;
    unitPrice: string;
    fixedPrice: string;
}

export interface QuoteData {
    services: ServiceBlock[];
    baseValue: string;
    vatOverride: string;
    estimatedTime: string;
    expirationDate: string;
    paymentConditions: string;
}

export interface SavedQuote {
    id: string;
    title: string;
    clientName: string;
    createdAt: string;
    updatedAt: string;
}

interface QuoteContextType {
    quote: QuoteData;
    currentQuoteId: string | null;
    updateQuote: (updates: Partial<QuoteData>) => void;
    addService: () => void;
    removeService: (id: string) => void;
    updateService: (id: string, updates: Partial<ServiceBlock>) => void;
    saveQuote: (clientName?: string, clientEmail?: string, clientWhatsapp?: string, clientServiceTitle?: string) => Promise<void>;
    loadQuote: (id: string) => Promise<void>;
    deleteQuote: (id: string) => Promise<void>;
    newQuote: () => void;
    savedQuotes: SavedQuote[];
    loadSavedQuotes: () => Promise<void>;
    isLoading: boolean;
    isSaving: boolean;
}

function createEmptyService(): ServiceBlock {
    return {
        id: crypto.randomUUID(),
        title: '',
        description: '',
        pricingMode: 'sqm',
        quantity: '',
        unitPrice: '',
        fixedPrice: '',
    };
}

const defaultQuote: QuoteData = {
    services: [createEmptyService()],
    baseValue: '',
    vatOverride: '',
    estimatedTime: '',
    expirationDate: '',
    paymentConditions: '',
};

const QuoteContext = createContext<QuoteContextType | undefined>(undefined);

export function QuoteProvider({ children }: { children: ReactNode }) {
    const { user } = useAuth();
    const supabase = createClient();
    const [quote, setQuote] = useState<QuoteData>(defaultQuote);
    const [currentQuoteId, setCurrentQuoteId] = useState<string | null>(null);
    const [savedQuotes, setSavedQuotes] = useState<SavedQuote[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isSaving, setIsSaving] = useState(false);

    // Load saved quotes list when user is available
    const loadSavedQuotes = useCallback(async () => {
        if (!user) return;

        try {
            const { data, error } = await supabase
                .from('quotes')
                .select('id, title, client_name, created_at, updated_at')
                .eq('user_id', user.id)
                .order('updated_at', { ascending: false });

            if (error) {
                console.error('Error loading quotes:', error);
                return;
            }

            setSavedQuotes(
                (data || []).map((q) => ({
                    id: q.id,
                    title: q.title || 'Untitled Quote',
                    clientName: q.client_name || '',
                    createdAt: q.created_at,
                    updatedAt: q.updated_at,
                }))
            );
        } catch (err) {
            console.error('Error loading quotes:', err);
        }
    }, [user, supabase]);

    useEffect(() => {
        if (user) {
            loadSavedQuotes();
        }
    }, [user]);

    const updateQuote = (updates: Partial<QuoteData>) => {
        setQuote((prev) => ({ ...prev, ...updates }));
    };

    const addService = () => {
        setQuote((prev) => ({
            ...prev,
            services: [...prev.services, createEmptyService()],
        }));
    };

    const removeService = (id: string) => {
        setQuote((prev) => ({
            ...prev,
            services: prev.services.filter((s) => s.id !== id),
        }));
    };

    const updateService = (id: string, updates: Partial<ServiceBlock>) => {
        setQuote((prev) => ({
            ...prev,
            services: prev.services.map((s) =>
                s.id === id ? { ...s, ...updates } : s
            ),
        }));
    };

    const saveQuote = useCallback(async (
        clientName?: string,
        clientEmail?: string,
        clientWhatsapp?: string,
        clientServiceTitle?: string
    ) => {
        if (!user) return;

        setIsSaving(true);
        try {
            const quoteRow = {
                user_id: user.id,
                title: quote.services[0]?.title || 'Untitled Quote',
                services: JSON.stringify(quote.services),
                base_value: parseFloat(quote.baseValue) || 0,
                vat_override: quote.vatOverride,
                estimated_time: quote.estimatedTime,
                expiration_date: quote.expirationDate,
                payment_conditions: quote.paymentConditions,
                client_name: clientName || '',
                client_email: clientEmail || '',
                client_whatsapp: clientWhatsapp || '',
                client_service_title: clientServiceTitle || '',
                updated_at: new Date().toISOString(),
            };

            if (currentQuoteId) {
                // Update existing quote
                const { error } = await supabase
                    .from('quotes')
                    .update(quoteRow)
                    .eq('id', currentQuoteId);

                if (error) throw error;
            } else {
                // Insert new quote
                const { data, error } = await supabase
                    .from('quotes')
                    .insert(quoteRow)
                    .select('id')
                    .single();

                if (error) throw error;
                if (data) setCurrentQuoteId(data.id);
            }

            // Refresh the saved quotes list
            await loadSavedQuotes();
        } catch (err) {
            console.error('Error saving quote:', err);
            throw err;
        } finally {
            setIsSaving(false);
        }
    }, [user, quote, currentQuoteId, supabase, loadSavedQuotes]);

    const loadQuote = useCallback(async (id: string) => {
        if (!user) return;

        setIsLoading(true);
        try {
            const { data, error } = await supabase
                .from('quotes')
                .select('*')
                .eq('id', id)
                .eq('user_id', user.id)
                .single();

            if (error) throw error;

            if (data) {
                let services: ServiceBlock[];
                try {
                    services = typeof data.services === 'string'
                        ? JSON.parse(data.services)
                        : data.services;
                } catch {
                    services = [createEmptyService()];
                }

                setQuote({
                    services: services.length > 0 ? services : [createEmptyService()],
                    baseValue: data.base_value?.toString() || '',
                    vatOverride: data.vat_override || '',
                    estimatedTime: data.estimated_time || '',
                    expirationDate: data.expiration_date || '',
                    paymentConditions: data.payment_conditions || '',
                });
                setCurrentQuoteId(data.id);
            }
        } catch (err) {
            console.error('Error loading quote:', err);
        } finally {
            setIsLoading(false);
        }
    }, [user, supabase]);

    const deleteQuote = useCallback(async (id: string) => {
        if (!user) return;

        try {
            const { error } = await supabase
                .from('quotes')
                .delete()
                .eq('id', id)
                .eq('user_id', user.id);

            if (error) throw error;

            // If we deleted the currently active quote, clear the form
            if (id === currentQuoteId) {
                setQuote({ ...defaultQuote, services: [createEmptyService()] });
                setCurrentQuoteId(null);
            }

            await loadSavedQuotes();
        } catch (err) {
            console.error('Error deleting quote:', err);
        }
    }, [user, currentQuoteId, supabase, loadSavedQuotes]);

    const newQuote = () => {
        setQuote({
            ...defaultQuote,
            services: [createEmptyService()],
        });
        setCurrentQuoteId(null);
    };

    return (
        <QuoteContext.Provider
            value={{
                quote, currentQuoteId, updateQuote, addService, removeService, updateService,
                saveQuote, loadQuote, deleteQuote, newQuote,
                savedQuotes, loadSavedQuotes,
                isLoading, isSaving,
            }}
        >
            {children}
        </QuoteContext.Provider>
    );
}

export function useQuote() {
    const context = useContext(QuoteContext);
    if (!context) {
        throw new Error('useQuote must be used within a QuoteProvider');
    }
    return context;
}

'use client';

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { createClient } from '@/lib/supabase-browser';
import { useAuth } from './AuthContext';

export interface SettingsData {
    companyName: string;
    email: string;
    phone: string;
    website: string;
    brandColor: string;
    currency: string;
    vatEnabled: boolean;
    vatPercentage: number;
    logoUrl: string | null;
    message: string;
    quoteDescription: string;
    taxCountry: string;
}

interface SettingsContextType {
    settings: SettingsData;
    updateSettings: (updates: Partial<SettingsData>) => void;
    saveSettings: (dataToSave?: SettingsData) => Promise<void>;
    isLoading: boolean;
    isSaving: boolean;
}

const defaultSettings: SettingsData = {
    companyName: '',
    email: '',
    phone: '',
    website: '',
    brandColor: '#1e3a5f',
    currency: '€',
    vatEnabled: true,
    vatPercentage: 23,
    logoUrl: null,
    message: '',
    quoteDescription: 'Quote Description',
    taxCountry: 'uk',
};

const SettingsContext = createContext<SettingsContextType | undefined>(undefined);

export function SettingsProvider({ children }: { children: ReactNode }) {
    const { user } = useAuth();
    const supabase = createClient();
    const [settings, setSettings] = useState<SettingsData>(defaultSettings);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);

    // Load settings from Supabase when user is available
    useEffect(() => {
        if (!user) {
            setSettings(defaultSettings);
            setIsLoading(false);
            return;
        }

        const loadSettings = async () => {
            setIsLoading(true);
            try {
                const { data, error } = await supabase
                    .from('user_settings')
                    .select('*')
                    .eq('user_id', user.id)
                    .single();

                if (error && error.code !== 'PGRST116') {
                    // PGRST116 = no rows found (first time user)
                    console.error('Error loading settings:', error);
                }

                if (data) {
                    setSettings({
                        companyName: data.company_name || '',
                        email: data.email || '',
                        phone: data.phone || '',
                        website: data.website || '',
                        brandColor: data.brand_color || '#1e3a5f',
                        currency: data.currency || '€',
                        vatEnabled: data.vat_enabled ?? true,
                        vatPercentage: data.vat_percentage ?? 23,
                        logoUrl: data.logo_url || null,
                        message: data.whatsapp_message || data.email_message || '',
                        quoteDescription: data.quote_description || 'Quote Description',
                        taxCountry: data.tax_country || 'uk',
                    });
                }
            } catch (err) {
                console.error('Error loading settings:', err);
            } finally {
                setIsLoading(false);
            }
        };

        loadSettings();
    }, [user]);

    const updateSettings = (updates: Partial<SettingsData>) => {
        setSettings((prev) => ({ ...prev, ...updates }));
    };

    const saveSettings = useCallback(async (dataToSave?: SettingsData) => {
        if (!user) return;

        // Use provided data (avoids stale closure), or fall back to current state
        const data = dataToSave ?? settings;

        setIsSaving(true);
        try {
            // Handle logo upload if it's a data URL (from crop)
            let logoUrl = data.logoUrl;
            if (logoUrl && logoUrl.startsWith('data:')) {
                // Convert data URL to blob and upload to Supabase Storage
                const response = await fetch(logoUrl);
                const blob = await response.blob();
                const rawExt = blob.type.split('/')[1] || 'png';
                const fileExt = rawExt.includes('svg') ? 'svg' : rawExt;
                const fileName = `${user.id}/logo.${fileExt}`;

                const { error: uploadError } = await supabase.storage
                    .from('logos')
                    .upload(fileName, blob, {
                        upsert: true,
                        contentType: blob.type,
                    });

                if (uploadError) {
                    console.error('Error uploading logo:', uploadError);
                } else {
                    const { data: urlData } = supabase.storage
                        .from('logos')
                        .getPublicUrl(fileName);
                    // Append cache-busting param so the browser fetches the new image
                    logoUrl = `${urlData.publicUrl}?t=${Date.now()}`;
                }
            }

            const { error } = await supabase
                .from('user_settings')
                .upsert({
                    user_id: user.id,
                    company_name: data.companyName,
                    email: data.email,
                    phone: data.phone,
                    website: data.website,
                    brand_color: data.brandColor,
                    currency: data.currency,
                    vat_enabled: data.vatEnabled,
                    vat_percentage: data.vatPercentage,
                    logo_url: logoUrl,
                    whatsapp_message: data.message,
                    email_message: data.message,
                    quote_description: data.quoteDescription,
                    tax_country: data.taxCountry,
                    updated_at: new Date().toISOString(),
                }, {
                    onConflict: 'user_id',
                });

            if (error) {
                console.error('Error saving settings:', error);
                throw error;
            }

            // Update local state with the stored logo URL
            if (logoUrl !== data.logoUrl) {
                setSettings((prev) => ({ ...prev, logoUrl }));
            }
        } catch (err) {
            console.error('Error saving settings:', err);
            throw err;
        } finally {
            setIsSaving(false);
        }
    }, [user, settings, supabase]);

    return (
        <SettingsContext.Provider value={{ settings, updateSettings, saveSettings, isLoading, isSaving }}>
            {children}
        </SettingsContext.Provider>
    );
}

export function useSettings() {
    const context = useContext(SettingsContext);
    if (!context) {
        throw new Error('useSettings must be used within a SettingsProvider');
    }
    return context;
}

import { jsPDF } from 'jspdf';
import type { SettingsData } from '../context/SettingsContext';
import type { QuoteData } from '../context/QuoteContext';

export interface ClientData {
    clientName: string;
    email: string;
    whatsapp: string;
    serviceTitle: string;
}

/* ── helpers ─────────────────────────────────────────────────── */

function hexToRGB(hex: string): [number, number, number] {
    const h = hex.replace('#', '');
    return [
        parseInt(h.substring(0, 2), 16),
        parseInt(h.substring(2, 4), 16),
        parseInt(h.substring(4, 6), 16),
    ];
}

async function loadImageAsBase64(url: string): Promise<string | null> {
    if (url.startsWith('data:')) return url;
    try {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.src = url;
        await new Promise<void>((ok, fail) => { img.onload = () => ok(); img.onerror = () => fail(); });
        const c = document.createElement('canvas');
        c.width = img.naturalWidth;
        c.height = img.naturalHeight;
        const ctx = c.getContext('2d');
        if (!ctx) return null;
        ctx.drawImage(img, 0, 0);
        return c.toDataURL('image/png');
    } catch { return null; }
}

function wrapText(pdf: jsPDF, text: string, maxWidth: number): string[] {
    const out: string[] = [];
    for (const para of text.split('\n')) {
        if (!para.trim()) { out.push(''); continue; }
        out.push(...(pdf.splitTextToSize(para, maxWidth) as string[]));
    }
    return out;
}

function getUnitLabel(mode: string) {
    if (mode === 'sqm') return 'm\u00B2';
    if (mode === 'hour') return 'hr';
    return '';
}

/*
 * ═══════════════════════════════════════════════════════
 *  generateQuotePDF
 *
 *  Uses POINTS as the unit so that 1 pt ≈ 1 CSS px.
 *  The preview is 595 px wide → PDF is 595 pt wide (=A4).
 *  Font sizes in pt match the CSS font-sizes in px.
 *  Paddings/margins match the CSS values exactly.
 * ═══════════════════════════════════════════════════════
 */

export async function generateQuotePDF(
    settings: SettingsData,
    quote: QuoteData,
    client?: ClientData,
): Promise<Blob> {

    // ── Page constants matching the CSS ──
    const W = 595;           // page width (= previewFrame 595px)
    const PAD = 40;          // side padding (= CSS padding: 40px)
    const CW = W - PAD * 2; // content width = 515

    // ── Load logo ──
    let logoB64: string | null = null;
    let logoW = 0, logoH = 0;
    if (settings.logoUrl) {
        logoB64 = await loadImageAsBase64(settings.logoUrl);
        if (logoB64) {
            try {
                const img = new Image();
                img.src = logoB64;
                await new Promise<void>((r) => { img.onload = () => r(); });
                // Logo area in CSS: 90×90 px
                logoW = 90; logoH = (img.naturalHeight / img.naturalWidth) * 90;
                if (logoH > 90) { logoH = 90; logoW = (img.naturalWidth / img.naturalHeight) * 90; }
            } catch { logoB64 = null; }
        }
    }

    // ── Calculate total height ──
    const m = new jsPDF('p', 'pt', 'a4');  // temp for text measurement
    let h = 40; // top padding (CSS: padding-top 40px in pdfHeader)

    // Header
    const hdrTextH = (settings.companyName ? 36 : 0) + // 22px font + 14px margin-bottom
        (settings.phone ? 16 : 0) +
        (settings.email ? 16 : 0) +
        (settings.website ? 16 : 0);
    h += Math.max(hdrTextH, logoH) + 28; // 28 = bottom padding of header

    // Description bar
    h += 29; // CSS: height 29px

    // Services area
    const filledServices = quote.services.filter(
        (s) => s.title || s.description || s.fixedPrice || (s.quantity && s.unitPrice),
    );
    if (filledServices.length > 0) {
        h += 30; // top padding of servicesArea
        for (const svc of filledServices) {
            h += 8 + 18; // serviceRow: margin-bottom 8 + title 18px line
            if (svc.description) {
                m.setFontSize(16);
                const lines = wrapText(m, svc.description, CW);
                h += lines.length * 16 * 1.7; // 16px font × 1.7 line-height
            }
            h += 28; // margin-bottom per service
        }
        h += 40; // bottom padding of servicesArea
    } else {
        // Even with no services, equal amount of padding
        h += 60;
    }

    // Totals divider bar
    h += 14; // CSS: height 14px

    // Bottom section
    h += 20; // padding-top
    h += 20 + 20 + 22; // baseValueLine×2 + totalValueLine
    if (quote.estimatedTime) h += 16 * 1.6;
    if (quote.expirationDate) h += 16 * 1.6;
    if (quote.paymentConditions) {
        m.setFontSize(15);
        h += wrapText(m, quote.paymentConditions, CW / 2).length * 15 * 1.6;
    }
    h += 36; // padding-bottom

    const PAGE_H = Math.max(h, 400);

    // ── Create the PDF ──
    const pdf = new jsPDF('p', 'pt', [W, PAGE_H]);
    let y = 40; // start at top padding

    const [br, bg, bb] = hexToRGB(settings.brandColor);

    // ════════ HEADER (CSS: padding 40px 40px 28px) ════════
    const headerTop = y;

    // Logo top-right
    if (logoB64 && logoW > 0) {
        const lx = W - PAD - logoW;
        try { pdf.addImage(logoB64, 'PNG', lx, headerTop, logoW, logoH); } catch { /* skip */ }
    }

    // Company info top-left
    let ty = headerTop;
    if (settings.companyName) {
        pdf.setFont('helvetica', 'bold');
        pdf.setFontSize(22);
        pdf.setTextColor(17, 17, 17);
        pdf.text(settings.companyName, PAD, ty + 22); // baseline offset ≈ font size
        ty += 36; // 22 + 14 margin-bottom
    }
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(15);
    pdf.setTextColor(68, 68, 68);
    if (settings.phone) { pdf.text(settings.phone, PAD, ty + 13); ty += 16; }
    if (settings.email) { pdf.text(settings.email, PAD, ty + 13); ty += 16; }
    if (settings.website) { pdf.text(settings.website, PAD, ty + 13); ty += 16; }

    y = headerTop + Math.max(ty - headerTop, logoH) + 28;

    // ════════ DESCRIPTION BAR (full width, 29px tall) ════════
    pdf.setFillColor(br, bg, bb);
    pdf.rect(0, y, W, 29, 'F');   // full width, no side margins
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(14);
    pdf.setTextColor(255, 255, 255);
    pdf.text(settings.quoteDescription || 'Quote Description', W / 2, y + 19, { align: 'center' });
    y += 29;

    // ════════ SERVICES (CSS: padding 30px 40px) ════════
    if (filledServices.length > 0) {
        y += 30; // top padding

        for (const svc of filledServices) {
            let priceStr = '';
            if (svc.pricingMode === 'fixed' && svc.fixedPrice) {
                priceStr = parseFloat(svc.fixedPrice).toFixed(2) + ' ' + settings.currency;
            } else if (svc.quantity && svc.unitPrice) {
                const u = getUnitLabel(svc.pricingMode);
                const t = (parseFloat(svc.quantity) * parseFloat(svc.unitPrice)).toFixed(2);
                priceStr = t + ' ' + settings.currency + ' (' + svc.quantity + ' ' + u + ')';
            }

            // Title (left) + price (right) on same line
            if (svc.title) {
                pdf.setFont('helvetica', 'bold');
                pdf.setFontSize(18);
                pdf.setTextColor(17, 17, 17);
                pdf.text(svc.title, PAD, y + 14);
            }
            if (priceStr) {
                pdf.setFont('helvetica', 'normal');
                pdf.setFontSize(14);
                pdf.setTextColor(34, 34, 34);
                const pw = pdf.getTextWidth(priceStr);
                pdf.text(priceStr, W - PAD - pw, y + 14);
            }
            y += 26; // serviceRow height + margin

            // Description
            if (svc.description) {
                pdf.setFont('helvetica', 'normal');
                pdf.setFontSize(16);
                pdf.setTextColor(68, 68, 68);
                const lines = wrapText(pdf, svc.description, CW);
                const lh = 16 * 1.7;
                for (const line of lines) {
                    pdf.text(line, PAD, y + 13);
                    y += lh;
                }
            }
            y += 28; // gap between services
        }
    } else {
        y += 60;
    }

    // ════════ TOTALS DIVIDER BAR (full width, 14px tall) ════════
    pdf.setFillColor(br, bg, bb);
    pdf.rect(0, y, W, 14, 'F');   // full width
    y += 14;

    // ════════ BOTTOM SECTION (CSS: padding 20px 40px 36px) ════════
    y += 20;

    const sVat = settings.vatEnabled ? settings.vatPercentage : 0;
    const vPct = quote.vatOverride !== '' ? (parseFloat(quote.vatOverride) || 0) : sVat;
    const base = parseFloat(quote.baseValue) || 0;
    const vatAmt = (base * vPct) / 100;
    const total = base + vatAmt;

    const bY = y; // save start for footer on left side

    // Totals — right-aligned using jsPDF align option
    const rx = W - PAD; // right edge

    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(16);
    pdf.setTextColor(51, 51, 51);

    const t1 = 'Price excluding VAT: ' + settings.currency + ' ' + (base > 0 ? base.toFixed(2) : '0.00');
    pdf.text(t1, rx, y + 13, { align: 'right' });
    y += 20;

    const t2 = 'VAT ' + vPct + '%: ' + settings.currency + ' ' + (base > 0 ? vatAmt.toFixed(2) : '0.00');
    pdf.text(t2, rx, y + 13, { align: 'right' });
    y += 20;

    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(18);
    pdf.setTextColor(17, 17, 17);
    const t3 = 'Total incl. VAT: ' + settings.currency + ' ' + (total > 0 ? total.toFixed(2) : '0.00');
    pdf.text(t3, rx, y + 14, { align: 'right' });

    // Footer — left side
    let fy = bY;
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(15);
    pdf.setTextColor(68, 68, 68);
    if (quote.estimatedTime) { pdf.text(quote.estimatedTime, PAD, fy + 13); fy += 16 * 1.6; }
    if (quote.expirationDate) { pdf.text(quote.expirationDate, PAD, fy + 13); fy += 16 * 1.6; }
    if (quote.paymentConditions) {
        const cl = wrapText(pdf, quote.paymentConditions, CW / 2);
        for (const ln of cl) { pdf.text(ln, PAD, fy + 13); fy += 15 * 1.6; }
    }

    return pdf.output('blob');
}

/* ── download helper ── */

export function downloadPDF(blob: Blob, filename: string = 'quote.pdf'): void {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}
